      "keystrokes": "cat > /workspace/scripts/list_models.mjs << 'EOF'
import http from 'http';

const options = {
  hostname: 'colormind.io',
  port: 80,
  path: '/list/',
  method: 'GET'
};

const req = http.request(options, (res) => {
  let data = '';
  res.on('data', (chunk) => data += chunk);
  res.on('end', () => console.log(data));
});

req.on('error', (e) => console.error('Error:', e.message));
req.end();
EOF\n",
      "duration": 0.1
    },
    {
      "keystrokes": "cat > /workspace/scripts/generate_palette.mjs << 'EOF'
import http from 'http';
import { argv } from 'process';

// Parse arguments
let model = 'default';
let input = ['N', 'N', 'N', 'N', 'N'];
let pretty = false;

let i = 2;
while (i < argv.length) {
  if (argv[i] === '--model' && argv[i + 1]) {
    model = argv[i + 1];
    i += 2;
  } else if (argv[i] === '--input' && argv[i + 1]) {
    input = argv.slice(i + 1).filter(a => !a.startsWith('--'));
    break;
  } else if (argv[i] === '--pretty') {
    pretty = true;
    i++;
  } else {
    i++;
  }
}

// Convert input to locked colors
const locked = input.map(slot => {
  if (slot === 'N') return null;
  const parts = slot.split(',');
  return parts.map(p => parseInt(p.trim()));
});

const data = JSON.stringify({ model, locked });

const options = {
  hostname: 'colormind.io',
  port: 80,
  path: '/api/',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(data)
  }
};

const req = http.request(options, (res) => {
  let body = '';
  res.on('data', (chunk) => body += chunk);
  res.on('end', () => {
    const result = JSON.parse(body);
    console.log(JSON.stringify(result, null, 2));

    if (pretty && result.palette) {
      console.log('\n--- Palette ---');
      result.palette.forEach((color, i) => {
        const hex = '#' + color.map(c => c.toString(16).padStart(2, '0')).join('');
        console.log(`Color ${i + 1}: RGB(${color[0]}, ${color[1]}, ${color[2]}) = ${hex}`);
      });
    }
  });
});

req.on('error', (e) => console.error('Error:', e.message));
req.write(data);
req.end();
EOF\n",
      "duration": 0.1
    },
    {
      "keystrokes": "ls -la /workspace/scripts/\n",
      "duration": 0.1
    }
  ]
}

